_CIE_ILLUMINANT_TENSOR = torch.tensor(
    CIE_ILLUMINANT_SPD_420_660_10NM, dtype=torch.float32
)


def cie_illuminants(device=None, dtype=torch.float32) -> torch.Tensor:
    return _CIE_ILLUMINANT_TENSOR.to(device=device, dtype=dtype)


def apply_cie_illuminant(
    hs_image: torch.Tensor,
    illuminant_index: int,
    exposure: float,
) -> torch.Tensor:
    if hs_image.ndim != 4:
        raise ValueError(f'Expected HS tensor [B,C,H,W], got {tuple(hs_image.shape)}')
    if hs_image.shape[1] != 25:
        raise ValueError('CIE augmentation requires 25 channels at 420--660 nm')
    if illuminant_index < 0:
        spectral_scale = torch.ones(
            (1, hs_image.shape[1], 1, 1),
            device=hs_image.device,
            dtype=hs_image.dtype,
        )
    else:
        if illuminant_index >= len(CIE_ILLUMINANT_NAMES):
            raise IndexError(f'Invalid CIE illuminant index: {illuminant_index}')
        spectral_scale = cie_illuminants(hs_image.device, hs_image.dtype)[
            illuminant_index
        ].view(1, -1, 1, 1)
    return hs_image * spectral_scale * float(exposure)


def translate_metric_depth(
    depth_metric: torch.Tensor,
    valid_mask: torch.Tensor,
    requested_shift_m: float,
    min_depth: float,
    max_depth: float,
) -> Tuple[torch.Tensor, float]:
    valid = valid_mask > 0.5
    background = torch.full_like(depth_metric, float(min_depth))
    if not torch.any(valid):
        return background, 0.0

    valid_depth = depth_metric[valid]
    lower_shift = float(min_depth) - float(valid_depth.min().item())
    upper_shift = float(max_depth) - float(valid_depth.max().item())
    applied_shift = min(max(float(requested_shift_m), lower_shift), upper_shift)
    shifted = torch.where(valid, depth_metric + applied_shift, background)
    return shifted.clamp(float(min_depth), float(max_depth)), applied_shift
